$(function () {
  let image = &quot;%2fPCUP%2fReligion-PNG%2fCalistria.png&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;#symbole1&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td id=&quot;symbole1&quot; style=&quot;text-align:center;&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux aux fid&#232;les de la divinit&#233; indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Calistria (technique).ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/%2fPCUP%2fReligion-PNG%2fCalistria.png&quot; style=&quot;max-height:70px; max-width:70px&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br/&gt;commune chez&lt;br/&gt;les fid&#232;les&lt;br/&gt;de &lt;a class=&quot;pagelink&quot; href=&quot;Calistria-(Technique).html&quot; title=&quot;Calistria&quot;&gt;Calistria&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Lame triple-dard&lt;div style=&quot;float:right;&quot;&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Dieux et magie (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Gods and Magic, Faiths of Purity, Faiths of Balance, Faiths of Corruption/Dieux et magie&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoG&amp;M.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Evocation.html&quot; title=&quot;&#201;vocation&quot;&gt;&#201;vocation&lt;/a&gt; faible ; &lt;b&gt;NLS&lt;/b&gt; 7 ; &lt;b&gt;Emplacement&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Magiques-Sp&#233;cifiques.html&quot; title=&quot;Armes magiques sp&#233;cifiques&quot;&gt;aucun (arme)&lt;/a&gt; ; &lt;b&gt;Prix&lt;/b&gt; 11 702 po ; &lt;b&gt;Poids&lt;/b&gt; 0,5 kg
&lt;div class=&quot;box&quot;&gt;Description&lt;/div&gt;
Cette &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dague-(Arme).html&quot; title=&quot;Dague&quot;&gt;dague&lt;/a&gt; +1&lt;/i&gt; hautement d&#233;corative comporte une rose grav&#233;e sur son pommeau et une garde ray&#233;e de noir et de jaune. Apr&#232;s examen, la lame semble &#234;tre bossel&#233;e &#224; intervalles r&#233;guliers. Ces bosses sont en fait des &#233;pines r&#233;tractables. Si le personnage utilise une &lt;i&gt;lame triple-dard&lt;/i&gt; et inflige avec succ&#232;s des d&#233;g&#226;ts &#224; une cr&#233;ature, il peut effectuer une &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html&quot; title=&quot;Les manœuvres offensives&quot;&gt;manœuvre offensive&lt;/a&gt; gratuite contre sa cible. S’il &#233;choue, rien ne se produit. S’il r&#233;ussit, il enfonce la lame assez profond&#233;ment dans la cible pour provoquer le jaillissement des &#233;pines et infliger 1d4 points de d&#233;g&#226;ts suppl&#233;mentaires. Les &#233;pines se r&#233;tractent imm&#233;diatement apr&#232;s avoir caus&#233; ces d&#233;g&#226;ts.&lt;br /&gt;&lt;br /&gt;Si &lt;a class=&quot;pagelink&quot; href=&quot;Calistria-(Technique).html&quot; title=&quot;Calistria&quot;&gt;Calistria&lt;/a&gt; est la divinit&#233; tut&#233;laire du personnage et qu’il murmure son nom, il peut, une fois par jour et par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt;, passer le bonus d’alt&#233;ration de la &lt;i&gt;lame triple-dard&lt;/i&gt; &#224; +2 pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;. Si le personnage n’est pas un suivant de la d&#233;esse et qu’il prononce son nom alors qu’il tient la &lt;i&gt;lame triple-dard&lt;/i&gt;, des &#233;pines jaillissent alors de la poign&#233;e et lui injectent un poison &#233;quivalent au &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html#Venindaraign&#233;edetailleM&quot; title=&quot;Les poisons  &quot;&gt;venin d’araign&#233;e de taille M&lt;/a&gt;.
&lt;div class=&quot;box&quot;&gt;Cr&#233;ation&lt;/div&gt;
&lt;b&gt;Conditions&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Darmes-Et-Armures-Magiques.html&quot; title=&quot;Cr&#233;ation d&amp;#39;armes et armures magiques&quot;&gt;Cr&#233;ation d&#39;armes et armures magiques&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Croissance-D&#233;pines.html&quot; title=&quot;Croissance d&amp;#39;&#233;pines&quot;&gt;croissance d’&#233;pines&lt;/a&gt;&lt;/i&gt; ; &lt;b&gt;Co&#251;t&lt;/b&gt; 5 851 po
&lt;/div&gt;
